        private FlowLayoutPanel Bar() {return new FlowLayoutPanel {Tag="toolbar",Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true,BackColor=Color.Transparent,Margin=Padding.Empty};}
        private Button AddButton(Control parent,string text,EventHandler click,bool edit) {var b=new ThemeButton {Text=text,AccessibleName=text,AutoSize=true,Height=34,MinimumSize=new Size(32,34),Tag="quiet",FlatStyle=FlatStyle.Flat,BackColor=panelColor,ForeColor=ink,Margin=new Padding(0,2,5,2),Padding=new Padding(6,0,6,0)};b.FlatAppearance.BorderColor=Color.FromArgb(210,220,232);b.Click+=delegate(object s,EventArgs e){try{click(s,e);}catch(Exception error){ShowError(error.Message);}};parent.Controls.Add(b);if(edit)editing.Add(b);if(text=="Edit step…"||text=="↑ Up"||text=="↓ Down"||text=="Duplicate block"||text=="Delete"||text=="Enable / disable"||text=="▶ From selected"||text=="▶ Selected block")selectionButtons.Add(b);tooltips.SetToolTip(b,ButtonHint(text));return b;}
        private int SelectedIndex {get{return list.FocusedItem!=null&&list.FocusedItem.Selected?list.FocusedItem.Index:list.SelectedIndices.Count>0?list.SelectedIndices[0]:-1;}}
        private Step Selected {get{return SelectedIndex>=0&&SelectedIndex<macro.Steps.Count?macro.Steps[SelectedIndex]:null;}}
        private void SetStatus(string text) {status.Text=text;}
        private void ShowError(string text) {SetStatus(text);if(headless)throw new InvalidOperationException(text);InAppDialog.Message(this,text,"MacroExecute",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
        private void RefreshList(int selected)
        {
            list.BeginUpdate();list.Items.Clear();var rows=StepRow.Describe(macro.Steps);for(int i=0;i<macro.Steps.Count;i++){Step s=macro.Steps[i];var item=new ListViewItem((i+1).ToString());item.ImageKey=s.Kind.ToString();item.Tag=rows[i];item.SubItems.Add(StepPresentation.Name(s)+(s.Enabled?"":"  [off]"));item.ToolTipText=StepPresentation.Name(s)+"\n"+(EditorBlocks.IsBoundary(s.Kind)?"Drag the IF or Repeat header to move this whole block.":"Drag this row to move it; IF and Repeat carry their whole block.")+"\n"+StepPresentation.Summary(s);item.SubItems.Add(StepPresentation.Summary(s));item.BackColor=UiTheme.RowColor(rows[i]);item.ForeColor=UiTheme.Ink;if(!s.Enabled)item.ForeColor=UiTheme.Muted;list.Items.Add(item);}if(selected>=0&&selected<list.Items.Count){list.Items[selected].Selected=true;list.Items[selected].EnsureVisible();}list.EndUpdate();list.FitStepNumbers();list.Visible=macro.Steps.Count>0;welcome.Visible=macro.Steps.Count==0;welcome.BringToFront();SelectStep();Text="MacroExecute — "+macro.Name+(dirty?" *":"");lastSnapshot=Storage.Encode(macro);RefreshCategoryHint();RefreshStepMatches();if(!busy)SetStatus(IdleStatus());
        }
        private void SelectStep(){RefreshStepMatches();UpdateSelectionHints();UpdateNavigation();properties.SelectedObject=ChosenRows.Length>1?null:Selected;inspectorHelp.Visible=!properties.Visible&&inspector.Height>=330;if(imagePreview.Image!=null){imagePreview.Image.Dispose();imagePreview.Image=null;}var step=Selected;stepGuide.Text=step==null?"Choose an action above to build your macro.\nDouble-click a step to open its guided settings.":StepPresentation.Name(step)+"\n"+(Plan.IsIf(step.Kind)?"True: insert after IF. False: insert after ELSE. Use the links below to jump between branches.":EditorBlocks.IsBoundary(step.Kind)?"This row closes or separates a block. Select its IF or Repeat header to edit, move, or delete the whole block.":StepPresentation.Summary(step));if(ChosenRows.Length>1)stepGuide.Text=ChosenRows.Length+" selected steps\nCtrl+C copy - Ctrl+X cut - Ctrl+V paste\nCtrl/Shift-click to select separate sections. Use File > Save selection as workflow to reuse them.";tooltips.SetToolTip(stepGuide,stepGuide.Text);inspectorHelp.Text=step==null?"New here? Open How to use for recipes and examples.":Plan.IsIf(step.Kind)?"Drag the IF header to move both branches together.":step.Kind==ActionKind.Repeat?"Drag the Repeat header to move the entire loop.":EditorBlocks.IsBoundary(step.Kind)?"Select the opening header to edit or move this block.":"Drag to reorder · Double-click to edit";tooltips.SetToolTip(inspectorHelp,step==null?"Open How to use for a practical guide.":ActionCatalog.Describe(step.Kind));if(step!=null&&!ImageTemplate.IsImage(step.Kind))imagePreview.Image=ActionArt.Icon(step.Kind,48);if(step!=null&&ImageTemplate.IsImage(step.Kind))try{var copy=step.Clone();if(!Path.IsPathRooted(copy.Target))copy.Target=Path.Combine(DocumentDirectory,copy.Target);imagePreview.Image=ImageTemplate.Load(copy);}catch{stepGuide.Text+="\nCapture or import a reference in Edit settings.";}}
        private void Snapshot() {undo.Push(Storage.Encode(macro));if(undo.Count>100){var keep=undo.Take(100).Reverse().ToArray();undo.Clear();foreach(string s in keep)undo.Push(s);}redo.Clear();}
        private void MarkDirty() {dirty=savedSnapshot!=Storage.Encode(macro);Text="MacroExecute — "+macro.Name+(dirty?" *":"");UpdateSelectionHints();}
        private void History(bool forward) {if(busy)return;var from=forward?redo:undo;var to=forward?undo:redo;if(from.Count==0)return;to.Push(Storage.Encode(macro));macro=Storage.Decode(from.Pop());MarkDirty();RefreshList(-1);}
        private bool ConfirmDiscard() {if(!dirty)return true;var answer=InAppDialog.Message(this,"Save changes to "+macro.Name+"?","Unsaved workflow",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);return answer==DialogResult.No||(answer==DialogResult.Yes&&Save(false));}
        private void NewDocument() {if(busy||!ConfirmDiscard())return;macro=new Macro();filename=null;dirty=false;undo.Clear();redo.Clear();savedSnapshot=Storage.Encode(macro);RefreshList(-1);}
        private void OpenDocument() {if(busy||!ConfirmDiscard())return;WorkflowPicker picker=null;using(picker=new WorkflowPicker(preferences.RecentFiles,delegate{return BrowseWorkflow(picker);}))if(InAppDialog.Show(this,picker)==DialogResult.OK)LoadFile(picker.SelectedPath);}
        private void LoadFile(string path) {var loaded=Storage.Load(path);macro=loaded;filename=Path.GetFullPath(path);dirty=false;undo.Clear();redo.Clear();Remember(filename);savedSnapshot=Storage.Encode(macro);RefreshList(-1);}
        private bool Save(bool choose) {if(busy)return false;string path=filename;if(choose||string.IsNullOrEmpty(path)){using(var d=WorkflowFiles.SaveDialog(filename)){if(d.ShowDialog(this)!=DialogResult.OK)return false;path=d.FileName;}} var prepared=Storage.Decode(Storage.Encode(macro));prepared.Name=WorkflowFiles.DisplayName(path);foreach(var imageStep in prepared.Steps)if(ImageTemplate.IsImage(imageStep.Kind)){if(string.IsNullOrEmpty(imageStep.ImageData)){var image=imageStep.Clone();image.Target=Plan.Resolve(DocumentDirectory,image.Target);ImageTemplate.Embed(image);imageStep.ImageData=image.ImageData;}}Storage.Save(path,prepared);macro=prepared;filename=Path.GetFullPath(path);dirty=false;Remember(filename);savedSnapshot=Storage.Encode(macro);RefreshList(SelectedIndex);return true;}
        private void Remember(string path) {preferences.RecentFiles=new[]{path}.Concat(preferences.RecentFiles??new string[0]).Distinct(StringComparer.OrdinalIgnoreCase).Take(8).ToArray();RefreshRecentFiles();}
        private void ShowRecent(Control owner) { OpenDocument(); }
        private string DocumentDirectory {get{return filename==null?AppDomain.CurrentDomain.BaseDirectory:Path.GetDirectoryName(filename);}}
        private void AddGallery(TabControl tabs,string title,ActionKind[] kinds){var page=new TabPage(title){Tag="gallery"};var bar=new RoundedFlow{Tag="gallery",Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true,Padding=new Padding(6,3,6,3),AccessibleName=title+" actions"};page.Controls.Add(bar);tabs.TabPages.Add(page);editing.Add(bar);foreach(var kind in kinds){ActionKind choice=kind;var b=ActionArt.Button(kind,delegate{try{AddStep(choice);}catch(Exception e){ShowError(e.Message);}});tooltips.SetToolTip(b,ActionCatalog.Describe(kind)+"\nInsert at the position shown above the timeline.");InstallActionHelp(b,kind);bar.Controls.Add(b);}if(title=="Common actions"||title=="Mouse & keyboard")bar.Controls.Add(ShortcutTile());RefreshCategoryHint();}
        private void AddStep(ActionKind kind){if(busy)return;var step=new Step{Kind=kind,Enabled=EnabledInsertion()};if(kind==ActionKind.IfClipboard)step.ClipboardMatch=ClipboardMatchMode.Rules;if(kind==ActionKind.MouseClick)step.Pointer=PointerMode.CurrentPointer;if(kind==ActionKind.Note)step.Text="Describe this part of the macro";using(var editor=new StepEditor(step,DocumentDirectory)){if(InAppDialog.Show(this,editor)!=DialogResult.OK)return;CommitAddedStep(editor.Value);}}
        private void EditSelected(){if(busy||ChosenRows.Length>1||Selected==null||EditorBlocks.IsBoundary(Selected.Kind))return;int index=SelectedIndex;using(var editor=new StepEditor(Selected,DocumentDirectory)){if(InAppDialog.Show(this,editor)!=DialogResult.OK)return;if(editor.Value.Kind!=Selected.Kind){ShowError("Change the action by inserting a new step.");return;}Snapshot();bool changed=Selected.Enabled!=editor.Value.Enabled;int end=EditorBlocks.End(macro.Steps,index);macro.Steps[index]=editor.Value;if(changed)for(int i=index+1;i<=end;i++)macro.Steps[i].Enabled=editor.Value.Enabled;MarkDirty();RefreshList(index);}}
        private void ToggleEnabled(){if(busy||Selected==null)return;if(ChosenRows.Length>1){int[] rows=SequenceSelection.Expand(macro.Steps,ChosenRows);bool state=!macro.Steps[rows[0]].Enabled;var candidate=macro.Steps.Select(s=>s.Clone()).ToList();foreach(int row in rows)candidate[row].Enabled=state;Plan.Build(new Macro{Steps=candidate},DocumentDirectory);Snapshot();macro.Steps=candidate;MarkDirty();RefreshList(rows[0]);return;}if(EditorBlocks.IsBoundary(Selected.Kind))return;Snapshot();int n=SelectedIndex,end=EditorBlocks.End(macro.Steps,n);bool enabled=!Selected.Enabled;for(int i=n;i<=end;i++)macro.Steps[i].Enabled=enabled;MarkDirty();RefreshList(n);}
        private void Delete(){if(busy||Selected==null)return;if(ChosenRows.Length>1){DeleteChosen();return;}if(EditorBlocks.IsBoundary(Selected.Kind)){SetStatus("Select the IF or Repeat row to delete its whole block.");return;}Snapshot();int n=SelectedIndex;macro.Steps.RemoveRange(n,EditorBlocks.End(macro.Steps,n)-n+1);MarkDirty();RefreshList(Math.Min(n,macro.Steps.Count-1));SetStatus("Deleted selection · "+KeyName(AppCommand.Undo)+" restores it.");}
        private new void Move(int direction){int n=SelectedIndex;if(busy||n<0||EditorBlocks.IsBoundary(Selected.Kind))return;int end=EditorBlocks.End(macro.Steps,n),target;if(direction<0){target=EditorBlocks.Previous(macro.Steps,n);if(target<0||Plan.IsIf(macro.Steps[target].Kind)&&EditorBlocks.End(macro.Steps,target)>=n||macro.Steps[target].Kind==ActionKind.Repeat&&EditorBlocks.End(macro.Steps,target)>=n)return;}else{int next=end+1;if(next>=macro.Steps.Count||EditorBlocks.IsBoundary(macro.Steps[next].Kind))return;target=EditorBlocks.End(macro.Steps,next)+1;}
            Snapshot();var block=macro.Steps.GetRange(n,end-n+1);macro.Steps.RemoveRange(n,block.Count);if(target>n)target-=block.Count;macro.Steps.InsertRange(target,block);MarkDirty();RefreshList(target);}
        private void Duplicate(){if(busy||Selected==null)return;if(ChosenRows.Length>1){Guard(delegate{PasteStepsPayload(Storage.Encode(SelectedWorkflow()));});return;}if(EditorBlocks.IsBoundary(Selected.Kind))return;Snapshot();int n=SelectedIndex,end=EditorBlocks.End(macro.Steps,n);macro.Steps.InsertRange(end+1,EditorBlocks.Copy(macro.Steps,n));MarkDirty();RefreshList(end+1);SetStatus("Duplicated "+(end-n+1)+" step(s) · "+KeyName(AppCommand.Undo)+" restores the previous version.");}
        private async Task PlayRange(bool block){if(busy||Selected==null)return;int n=SelectedIndex;if(EditorBlocks.IsBoundary(Selected.Kind)){SetStatus("Select an action or the start of a block.");return;}int end=block?EditorBlocks.End(macro.Steps,n):macro.Steps.Count-1;var selected=new Macro{RandomSeed=macro.RandomSeed,Name=macro.Name,Steps=macro.Steps.GetRange(n,end-n+1).Select(x=>x.Clone()).ToList()};try{Plan.Build(selected,DocumentDirectory);}catch(Exception e){ShowError("The selection needs complete IF / Repeat blocks. "+e.Message);return;}await PlayMacro(selected,false);}
        private void SetBusy(bool value) {busy=value;foreach(Control c in editing)c.Enabled=!value;moves.Enabled=relative.Enabled=forever.Enabled=speed.Enabled=!value;repetitions.Enabled=!value&&!forever.Checked;recordButton.Enabled=!value||recorder.Active;playButton.Enabled=!recorder.Active;pauseButton.Enabled=value;stopButton.Enabled=value;RefreshTransport();UpdateSelectionHints();UpdateNavigation();}
        private void ToggleRecord()
        {
            if(OwnedForms.Length>0)return;if(recordingSession){Stop();return;}if(busy)return;if(hotkeys==null||!hotkeys.Registered(AppCommand.Stop))throw new InvalidOperationException("The Stop shortcut ("+KeyName(AppCommand.Stop)+") is unavailable. Choose another combination in Settings → Keyboard shortcuts.");recordingInsert=InsertionIndex;recordingEnabled=EnabledInsertion();recorder.RecordMoves=moves.Checked;recorder.RelativeCoordinates=relative.Checked;recorder.Start();recordingSession=true;SetBusy(true);WindowState=FormWindowState.Minimized;SetStatus(ShortcutText("Recording — F8 or F10 stops. MacroExecute's own inputs are excluded."));
        }
        private void Stop()
        {
            if(recordingSession){var recorded=recorder.Stop();recordingSession=false;CommitRecording(recorded,recordingInsert,recordingEnabled);SetBusy(false);WindowState=FormWindowState.Normal;Activate();RefreshList(recorded.Count>0?recordingInsert:-1);SetStatus(recorded.Count==0?"No recorded steps added. The macro is unchanged.":"Recorded "+recorded.Count+" steps starting at step "+(recordingInsert+1)+" · "+KeyName(AppCommand.Undo)+" undoes the recording.");return;}if(cancellation!=null)cancellation.Cancel();
        }
        private void TogglePause() {if(recordingSession){recorder.TogglePause();SetStatus(recorder.Paused?ShortcutText("Recording paused — Pause or F9 resumes, F10 finishes."):"Recording resumed.");RefreshTransport();return;}if(runner!=null&&busy){runner.Paused=!runner.Paused;SetStatus(runner.Paused?ShortcutText("Paused — F9 resumes, F10 stops."):"Playback resumed.");RefreshTransport();}}
        private Task Play(bool automatic){return PlayMacro(macro,automatic);}
        private async Task PlayMacro(Macro playing,bool automatic)
        {
            if(!busy&&playing.Steps.Count==0){SetStatus("Add or record a step first.");return;}
            if(busy){TogglePause();return;}
            if(OwnedForms.Length>0)return;CancellationTokenSource source=null;
            try {
                if(hotkeys==null||!hotkeys.Registered(AppCommand.Stop))throw new InvalidOperationException("The Stop shortcut ("+KeyName(AppCommand.Stop)+") is unavailable. Choose another combination in Settings → Keyboard shortcuts.");string directory=filename==null?AppDomain.CurrentDomain.BaseDirectory:Path.GetDirectoryName(filename);Plan plan=Plan.Build(playing,directory);if(plan.Steps.Count==0){SetStatus("Add or record a step first.");return;}
                source=new CancellationTokenSource();cancellation=source;runner=new Runner(new WindowsHost(this));runner.PauseChanged+=delegate{if(IsDisposed)return;if(InvokeRequired)BeginInvoke((Action)RefreshTransport);else RefreshTransport();};runner.Progress+=delegate(int index,Step step){SetStatus("Playing "+(index+1)+" / "+plan.Steps.Count+" — "+StepPresentation.Name(step)+"   •   "+KeyName(AppCommand.PlayPause)+" pause / "+KeyName(AppCommand.Stop)+" stop");RefreshTransport();};SetBusy(true);
                for(int i=3;i>0;i--){SetStatus("Playback starts in "+i+" — switch to your target application. "+KeyName(AppCommand.Stop)+" cancels.");await Task.Delay(1000,source.Token);}WindowState=FormWindowState.Minimized;
                await runner.Run(plan,forever.Checked?0:(int)repetitions.Value,(double)speed.Value,source.Token);SetStatus("Playback complete.");if(automatic&&closingAfterRun){dirty=false;BeginInvoke((Action)Close);}
            }catch(OperationCanceledException){SetStatus("Stopped. Synthesized held inputs released.");}catch(Exception e){ShowError(e.Message);}finally{cancellation=null;runner=null;if(source!=null)source.Dispose();SetBusy(false);WindowState=FormWindowState.Normal;}
        }
        private void Export() {if(busy)return;Plan.Build(macro,filename==null?AppDomain.CurrentDomain.BaseDirectory:Path.GetDirectoryName(filename));using(var d=new SaveFileDialog {Filter="MacroExecute player|*.exe",FileName="My flow.exe"})if(d.ShowDialog(this)==DialogResult.OK){var portable=new Macro{RandomSeed=macro.RandomSeed,Name=macro.Name,Steps=Plan.Build(macro,filename==null?AppDomain.CurrentDomain.BaseDirectory:Path.GetDirectoryName(filename)).Steps};foreach(var step in portable.Steps)if(ImageTemplate.IsImage(step.Kind))ImageTemplate.Embed(step);Portable.Export(Application.ExecutablePath,d.FileName,portable);SetStatus("Exported player. It opens a preview; press Play to run. Image templates are embedded. Other external files remain dependencies.");}}
        private void Schedule() {if(busy||!Save(false))return;using(var form=new ScheduleForm(delegate(DateTime when,bool daily){Plan.Build(macro,Path.GetDirectoryName(filename));return Scheduling.Create(Application.ExecutablePath,filename,when,daily);}))if(InAppDialog.Show(this,form)==DialogResult.OK)SetStatus("Schedule created · manage or remove it in Windows Task Scheduler.");}
        private static string BrowseWorkflow(IWin32Window owner) { using(var file=WorkflowFiles.OpenDialog())return file.ShowDialog(owner)==DialogResult.OK?file.FileName:null; }
        private void Randomization() { if(busy)return;using(var form=new RandomizationForm(macro.RandomSeed))if(InAppDialog.Show(this,form)==DialogResult.OK&&macro.RandomSeed!=form.Seed){Snapshot();macro.RandomSeed=form.Seed;MarkDirty();SetStatus(form.Seed.HasValue?"Fixed random seed: "+form.Seed.Value:"Random choices vary each playback.");} }
        private void Permissions()
        {
            if(busy)return;
            string mode=InputPermissions.CurrentMode();
            if(mode=="Administrator"||mode=="UIAccess token"){InAppDialog.Message(this,"Current mode: "+mode+".\nWindows secure desktops and applications that reject simulated input remain restricted.","Windows permissions");return;}
            if(InAppDialog.Message(this,"Current mode: "+mode+".\n\nRestart as administrator only when your target application also runs as administrator. Every workflow action and script will then share those privileges.\n\nSave your workflow and restart? Playback will not start automatically.","Windows permissions",MessageBoxButtons.OKCancel,MessageBoxIcon.Information)!=DialogResult.OK)return;
            if((dirty||filename==null&&macro.Steps.Count>0)&&!Save(false))return;
            var start=new ProcessStartInfo(Application.ExecutablePath,filename==null?"":Scheduling.Quote(filename)){UseShellExecute=true,Verb="runas",WorkingDirectory=AppDomain.CurrentDomain.BaseDirectory};
            try{var process=Process.Start(start);if(process!=null){process.Dispose();Close();}}catch(System.ComponentModel.Win32Exception error){if(error.NativeErrorCode!=1223)throw;SetStatus("Administrator restart cancelled. Your workflow remains open.");}
        }
        private void OpenPreferences()
        {
            if(busy)return;var current=Storage.Serializer().Deserialize<Preferences>(Storage.Serializer().Serialize(preferences));current.RecordMoves=moves.Checked;current.RelativeCoordinates=relative.Checked;current.Repetitions=forever.Checked?0:(int)repetitions.Value;current.Speed=(double)speed.Value;using(var form=new PreferencesForm(current))if(InAppDialog.Show(this,form)==DialogResult.OK){var edited=form.Value;if(!headless)edited.Save();preferences.DarkMode=edited.DarkMode;preferences.AccentStyle=edited.AccentStyle;preferences.RecordMoves=edited.RecordMoves;preferences.RelativeCoordinates=edited.RelativeCoordinates;preferences.Repetitions=edited.Repetitions;preferences.Speed=edited.Speed;moves.Checked=edited.RecordMoves;relative.Checked=edited.RelativeCoordinates;forever.Checked=edited.Repetitions==0;repetitions.Value=Math.Max(1,edited.Repetitions);speed.Value=(decimal)edited.Speed;ApplyTheme();RefreshIdleStatus();}
        }
        private void Bindings()
        {
            if(busy)return;WorkflowBindingsForm form=null;using(form=new WorkflowBindingsForm(preferences.HotkeyFiles,preferences.ActionShortcuts,delegate{return BrowseWorkflow(form);}))if(InAppDialog.Show(this,form)==DialogResult.OK){var before=preferences.HotkeyFiles;preferences.HotkeyFiles=form.Value;try{if(!headless)preferences.Save();}catch{preferences.HotkeyFiles=before;throw;}if(!headless)RegisterBindings();}
        }
        private void RegisterBindings(){foreach(int id in registered.Where(id=>id>=101).ToArray()){Native.UnregisterHotKey(Handle,id);registered.Remove(id);}var files=preferences.HotkeyFiles??new string[0];for(int i=0;i<Math.Min(9,files.Length);i++)if(!string.IsNullOrWhiteSpace(files[i])){if(Native.RegisterHotKey(Handle,101+i,0x4003,(uint)(49+i)))registered.Add(101+i);else SetStatus("Ctrl+Alt+"+(i+1)+" is already in use; that binding is inactive.");}}
        private async Task PlayBinding(int index){try{if(InAppDialog.IsOpen(this))return;if(busy){SetStatus("Stop the current workflow before starting a binding.");return;}if(preferences.HotkeyFiles==null||index>=preferences.HotkeyFiles.Length||string.IsNullOrWhiteSpace(preferences.HotkeyFiles[index]))return;if(!ConfirmDiscard())return;LoadFile(preferences.HotkeyFiles[index]);await Play(false);}catch(Exception e){ShowError(e.Message);}}
        private void Help(){ShowGuide(Selected==null?(ActionKind?)null:Selected.Kind);}
        private void ShowGuide(ActionKind? kind){using(var guide=new GuideCenter(kind))InAppDialog.Show(this,guide);}

        private void RegisterKeys(){hotkeys=new HotkeyManager(new WindowsHotkeyRegistrar(Handle));string error;if(!hotkeys.TryApply(preferences.ActionShortcuts,out error))SetStatus(error);RegisterBindings();}
        protected override void Dispose(bool disposing){if(disposing){dragScroll.Dispose();InWindowMenu.Close(this);if(themeButton!=null&&themeButton.Image!=null){themeButton.Image.Dispose();themeButton.Image=null;}foreach(var popup in navigationMenus)popup.Dispose();if(navigation!=null)navigation.Dispose();if(hotkeys!=null)hotkeys.Dispose();tooltips.Dispose();if(imagePreview.Image!=null){imagePreview.Image.Dispose();imagePreview.Image=null;}actionImages.Dispose();foreach(var icon in ownedIcons)icon.Dispose();ownedIcons.Clear();}base.Dispose(disposing);}
        protected override void WndProc(ref Message message){if(message.Msg==0x312){int id=message.WParam.ToInt32();if(id>=1&&id<=4){var task=Dispatch((AppCommand)id);}else if(id>=101&&id<=109){var task=PlayBinding(id-101);}}base.WndProc(ref message);}
        protected override bool ProcessCmdKey(ref Message message,Keys keyData){if(InAppDialog.IsOpen(this))return base.ProcessCmdKey(ref message,keyData);if(SelectionKey(keyData))return true;if(keyData==Keys.F1&&!Shortcuts.Find(preferences.ActionShortcuts,keyData).HasValue){if(!busy)Help();return true;}var command=Shortcuts.Find(preferences.ActionShortcuts,keyData);if((actionSearch.ContainsFocus||stepSearch.ContainsFocus)&&(keyData==Keys.Enter||keyData==(Keys.Shift|Keys.Enter)||keyData==Keys.Escape))return base.ProcessCmdKey(ref message,keyData);if(command.HasValue){if(Shortcuts.Global(command.Value))return true;Control focus=ActiveControl;while(focus is ContainerControl&&((ContainerControl)focus).ActiveControl!=null)focus=((ContainerControl)focus).ActiveControl;if((focus is TextBoxBase||focus is NumericUpDown||properties.ContainsFocus)&&Shortcuts.TextEditorOwns(keyData))return base.ProcessCmdKey(ref message,keyData);var task=Dispatch(command.Value);return true;}return base.ProcessCmdKey(ref message,keyData);}

    }

